window.products.push({"id":1107218,"name":"Wingscapes WSBR01 BirdCam Mounting Arm","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/31z7YInsc9L._AC_.jpg","description":"This Mounting Arm accessory makes it easy to mount your BirdCam or PlantCam to a pole, post, or tree. Easy setup. No tools required. Mounts on any bird feeder pole with an outside diameter of 0-1/2-1-1/2-inches, or to any post, wall, or tree. Has a unique 'elbow' joint that adjusts the mounting arm to angles of -60, -30, 0, 30 and 60 degrees. The 'ball joint' on the mounting arm connects to the standard tripod mount at the bottom of the BirdCam allowing the BirdCam to swivel 360 degrees. Dimensions: 2.25 by 3 by 23-1/2. Black. Mounting arm only; BirdCam and PlantCam not included.","images":["https://m.media-amazon.com/images/I/31z7YInsc9L._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Wingscapes","source_asin":"B0014C0A3A","category_path":"Home & Kitchen"},"sku":"BM-1107218","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0014C0A3A","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0014C0A3A","price_pending":true,"merchant_ready":false});
